 assert shape=={'channels':1,'sample_width':2,'rate':8000,'frames':800,'silence':True}
 return {'bytes':len(b),'sha256':sha(b),'PCM_bytes':len(pcm),'PCM_sha256':sha(pcm),'shape':shape},pcm
