 return {'marker':MARKER,'phase':stage,'python':platform.python_version(),'architecture':platform.machine(),'requested_python':os.environ.get('PYTHON_VERSION'),'files':files,'wav':wav,'converted_at_runtime':stage=='runtime','media':media_info(output),'retained_build_media':media_info('qa382-output.mp3') if stage=='runtime' else None,'tools':{n:tool(n) for n in ('ffmpeg','ffprobe','python','pip','poetry')}}
