 assert len(AudioSegment.from_wav('qa382-input.wav'))==100;print(MARKER+'_SOURCE_AND_WAV_CONFIRMED',flush=True)
elif '--build' in sys.argv:
 value=snapshot('build');Path('qa382-built.json').write_text(json.dumps(value,ensure_ascii=False));print('QA382_BUILD '+json.dumps(value,ensure_ascii=False),flush=True)
